B.ac3=new A.du([B.cy,"Koperen Nacht Tripel","Goudkoper van kleur met een romige schuimkraag. Kruidig, tonen van karamel en een warme afdronk. Gevaarlijk doordrinkbaar.",u.P,"Sanne",4.5])
B.cW=new A.jd(1,"tip")
B.acm=new A.du([B.cW,"Spoel je glas eerst koud om","Een koud gespoeld glas zorgt voor een mooiere schuimkraag en voorkomt dat je bier te snel opwarmt.",null,"BierKompas",null])
B.ac_=new A.du([B.cz,"Waarom heet het trappist?",'Een bier mag het logo "Authentic Trappist Product" alleen dragen als het onder toezicht van monniken binnen een trappistenabdij wordt gebrouwen.',null,null,null])
B.ach=new A.du([B.cy,"Amber Kompas IPA","Fris bitter met grapefruit en dennen, maar de moutbasis houdt alles mooi in balans. Een perfect terrasbier.",null,"Joris",4])
B.ac1=new A.du([B.cW,"Schenk schuin, eindig recht","Houd het glas schuin tijdens het inschenken en zet het halverwege rechtop. Zo krijg je een kraag van ongeveer twee vingers.",null,"BierKompas",null])
B.ac7=new A.du([B.cz,"Bock komt uit Einbeck","De naam bockbier is waarschijnlijk een verbastering van Einbeck, een Duitse stad die in de middeleeuwen bekend was om zijn sterke bier.",null,null,null])
B.ac8=new A.du([B.cy,"Donkere Molen Stout","Koffie, pure chocolade en een fluweelzachte mondvulling. Laat hem iets opwarmen, dan komt de vanille los.",null,"Fatima",4.5])
B.acp=new A.du([B.cW,"Niet elk bier hoort ijskoud","Pils smaakt het best rond 3 tot 5 graden, maar dubbels, tripels en stouts komen pas echt tot hun recht rond 8 tot 12 graden.",null,"BierKompas",null])
B.aco=new A.du([B.cz,"Hop is familie van hennep","Hop en hennep horen allebei bij de plantenfamilie Cannabaceae. Hop geeft bier bitterheid, aroma en een langere houdbaarheid.",null,null,null])
B.acg=new A.du([B.cy,"Zomerhaven Witbier","Troebel, met citrus en koriander. Iets te zoet naar mijn smaak, maar heerlijk als het buiten 25 graden is.",u.c,"Daan",3.5])
B.acd=new A.du([B.cW,"Bewaar flessen rechtop","Rechtop, koel en donker bewaard blijft bier langer goed. Licht kan zorgen voor een onaangename, muffe smaak.",null,"BierKompas",null])
B.ac9=new A.du([B.cz,"Spontane vergisting","Lambiek wordt spontaan vergist met wilde gisten en bacteri\xebn uit de lucht, traditioneel in de regio rond Brussel.","https://lh3.googleusercontent.com/aida-public/AB6AXuDknuVmwDTa5jB4wik1JsFZcg3HGHEguJ8tKYPIGvMOxeMgWo55nIZ92P0i_iTaZK5gCmhHDfSDDGd8HAgulU_Nt_waa4YIg1QNZCDQnGG9J70xbRh0XNaZFjxojqCPad3s7iiMSHzET5kRpj3GQcD9-hE4MuWtaKdUaP4Wkk6S1kxJhurPAITpPBmmuOIAnJ0_rU6wNjOB6JuYsppLKZZ370oFdfVTbvOpttwPVmC3aU02O1rJkSR2",null,null])
B.ac4=new A.du([B.cy,"Oude Sluis Dubbel","Rozijnen, bruine suiker en een vleugje drop. Een klassieke dubbel zonder poespas.",null,"Emma",4])
B.aca=new A.du([B.cW,"Stout bij chocolade","De geroosterde tonen van een stout versterken een chocoladedessert. Probeer het eens met een brownie.",null,"BierKompas",null])
B.acl=new A.du([B.cz,"Gueuze is een blend","Gueuze ontstaat door jonge en oude lambiek te mengen en op fles na te laten gisten. Daardoor krijgt het zijn bruisende, zure karakter.",null,null,null])
B.ac6=new A.du([B.cy,"Veldkers Saison","Droog, peperig en licht fruitig. Elke slok maakt dorst naar de volgende.",null,"Luuk",4.5])
B.acn=new A.du([B.cW,"Witbier bij vis en mosselen","De citrus- en korianderaroma's van witbier passen perfect bij vis, mosselen en frisse salades.",null,"BierKompas",null])
B.aci=new A.du([B.cz,"Het Reinheitsgebot","In 1516 bepaalde Beieren dat bier alleen van water, gerst en hop gemaakt mocht worden. Gist werd pas later ontdekt en toegevoegd.",null,null,null])
B.ack=new A.du([B.cy,"Koperen Nacht Blond","Honingzoet begin en een licht bittere finish. Toegankelijk, maar het mist wat karakter.",null,"Noor",3])
B.abZ=new A.du([B.cW,"Proef van licht naar zwaar","Begin een proeverij met lichte, frisse bieren en werk toe naar zware en zure bieren, zodat je smaakpapillen niet overweldigd raken.",null,"BierKompas",null])
B.ac2=new A.du([B.cz,"Donker is niet sterker","De kleur van bier komt van de mout, niet van het alcoholpercentage. Een donkere stout kan lichter zijn dan een blonde tripel.",null,null,null])
B.ace=new A.du([B.cy,"Winterlicht Bock","Karamel en geroosterd brood: precies wat je wilt als het buiten stormt.",null,"Milan",4])
B.ac5=new A.du([B.cW,"Ruik voordat je proeft","Een groot deel van wat je proeft is eigenlijk geur. Houd het glas even onder je neus voor de eerste slok.",null,"BierKompas",null])
B.abY=new A.du([B.cz,"K\xf6lsch is een beschermde naam","Volgens de K\xf6lsch-Konvention mag alleen bier dat in en rond Keulen wordt gebrouwen zich K\xf6lsch noemen.",null,null,null])
B.acq=new A.du([B.cy,"Havenmeester Pale Ale","Mooi helder, bloemige hop en een droge afdronk. Een echte allrounder.",u.y,"Lotte",4])
B.acb=new A.du([B.cW,"Kies het juiste glas","Een tulpglas houdt het aroma van speciaalbier vast; een smal pilsglas houdt het koolzuur langer vast.",null,"BierKompas",null])
B.ac0=new A.du([B.cz,"Witbier kwam terug dankzij een melkboer","Nadat witbier in Belgi\xeb was verdwenen, bracht melkboer Pierre Celis de stijl in 1966 terug in Hoegaarden.",null,null,null])
B.acc=new A.du([B.cy,"Kelderzuur Kriek","Zuur, kersen en een tikje amandel. Niet voor iedereen, wel voor mij.",null,"Yara",5])
B.acf=new A.du([B.cW,"Laat de gist in de fles","Bij bieren met nagisting op fles zit gistbezinksel onderin. Schenk rustig en laat het laatste bodempje staan.",null,"BierKompas",null])
B.acj=new A.du([B.cz,"De kraag doet ertoe","De schuimkraag houdt aroma's vast, zodat je neus meeproeft. Zonder kraag verliest bier sneller zijn geur.",null,null,null])
